class MG {
  constructor(K){ this.K=K; this.map=new Map(); }
  add(x){ if(this.map.has(x)) this.map.set(x,this.map.get(x)+1); else if(this.map.size<this.K) this.map.set(x,1); else { for(let [k,c] of this.map){ this.map.set(k,c-1); } /* remove zeros */ for(let [k,c] of Array.from(this.map)) if(this.map.get(k)<=0) this.map.delete(k); } }
